class AUTIL_SCOPED_LOCKABLE ScopedReadWriteLock {
private:
    ReadWriteLock &_lock;
    char _mode;

private:
    ScopedReadWriteLock(const ScopedReadWriteLock &);
    ScopedReadWriteLock &operator=(const ScopedReadWriteLock &);

public:
    // annotate it as exclusive lock for now, no way to annotate a lock with mode as parameter.
    explicit ScopedReadWriteLock(ReadWriteLock &lock, const char mode) AUTIL_EXCLUSIVE_LOCK_FUNCTION(lock)
        : _lock(lock), _mode(mode) {
        if (_mode == 'r' || _mode == 'R') {
            int ret = _lock.rdlock();
            ERRNO_FATAL(ret);
        } else if (_mode == 'w' || _mode == 'W') {
            int ret = _lock.wrlock();
            ERRNO_FATAL(ret);
        }
    }

    ~ScopedReadWriteLock() AUTIL_UNLOCK_FUNCTION() {
        if (_mode == 'r' || _mode == 'R' || _mode == 'w' || _mode == 'W') {
            int ret = _lock.unlock();
            ERRNO_FATAL(ret);
        }
    }
};

class Notifier {
public:
    static const int EXITED;

public:
    Notifier(int accumulatedNotificationMax = std::numeric_limits<int>::max())
        : _accumulatedNotification(0), _exitFlag(false), _accumulatedNotificationMax(accumulatedNotificationMax) {}

    int notifyExit() {
        ScopedLock lock(_cond);
        _exitFlag = true;
        return _cond.broadcast();
    }

    int notify() {
        ScopedLock lock(_cond);
        if (++_accumulatedNotification > _accumulatedNotificationMax) {
            _accumulatedNotification = _accumulatedNotificationMax;
            return 0;
        } else {
            return _cond.signal();
        }
    }

    bool isExit() const {
        ScopedLock lock(_cond);
        return _exitFlag;
    }

    /**
     * return 0 if got notified, and
     * return errno or EXITED
     */
    int waitNotification(int timeout = -1) { return wait(timeout); }

private:
    mutable ThreadCond _cond;
    int _accumulatedNotification;
    bool _exitFlag;
    int _accumulatedNotificationMax;

private:
    int wait(int timeout = 0) {
        ScopedLock lock(_cond);
        while (true) {
            if (_exitFlag) {
                return EXITED;
            }

            if (_accumulatedNotification > 0) {
                _accumulatedNotification = _accumulatedNotification - 1;
                return 0;
            }

            int ret = _cond.wait(timeout);
            if (ret != 0) {
                return ret;
            }
        }
    }
};

class TerminateClosure {
public:
    TerminateClosure() {}
    virtual ~TerminateClosure() {}

public:
    virtual void Run() = 0;
};

class TerminateNotifier {
public:
    static const int EXITED = (1 << 16) + 1;

public:
    TerminateNotifier() : _count(0), _exitFlag(false), _closure(NULL) {}
    /***
        dec must be called with inc in pair.
        And dec must be called after inc.
     */
    int inc() {
        autil::ScopedLock lock(_cond);
        _count = _count + 1;
        return 0;
    }
    int dec() {
        TerminateClosure *closure = NULL;
        int ret = 0;
        // get closure out of the lock range
        // to prevent "Run" delete "this"
        {
            // ENTER LOCK RANGE
            autil::ScopedLock lock(_cond);
            _count = _count - 1;
            assert(_count >= 0);
            if (_count == 0) {
                if (_closure) {
                    closure = _closure;
                    _closure = NULL;
                }
                ret = _cond.broadcast();
            }
            // LEAVE LOCK RANGE
        }

        if (closure) {
            closure->Run();
        }
        return ret;
    }
    /**
     return 0 if got notified, and
     return errno or EXITED
     ether onTerminate or wait can be called, but not together
     */
    int wait(int timeout = -1) {
        autil::ScopedLock lock(_cond);
        while (true) {
            if (_count == 0) {
                return 0;
            }

            if (_exitFlag) {
                return EXITED;
            }

            int ret = _cond.wait(timeout);
            if (ret != 0) {
                return ret;
            }
        }
    }
    int peek() {
        autil::ScopedLock lock(_cond);
        return _count;
    }
    /*
      After onTerminate, NO MORE inc and dec should be called.
      The closure will be call only once.
      The closure MUST be self deleted or deleted by outer caller.

      ether onTerminate or wait can be called, but not together
    */
    int onTerminate(TerminateClosure *closure) {
        {
            // ENTER LOCK RANGE
            autil::ScopedLock lock(_cond);
            if ((_count == 0) && (closure)) {
                // event happen, and the new closure is not NULL
                // new closure should be called right now
                _closure = NULL;
            } else {
                // event not happen yet, or NULL is set
                // simply save it
                _closure = closure;
                return 0;
            }
            // LEAVE LOCK RANGE
        }

        if (closure) {
            closure->Run();
        }
        return 0;
    }
    /*
        int notifyExit()
        {
            autil::ScopedLock lock(_cond);
            _exitFlag = true;
            // FIXME: may not alloc by new
            if (_closure) {
                delete _closure;
                _closure = NULL;
            }
            return _cond.broadcast();
        }
    */
private:
    volatile int _count;
    volatile bool _exitFlag;
    autil::ThreadCond _cond;
    TerminateClosure *_closure;
};

class TicketSpinLock {
public:
    TicketSpinLock() : users(0), ticket(0) {}
    ~TicketSpinLock() {}

private:
    TicketSpinLock(const TicketSpinLock &) = delete;
    TicketSpinLock &operator=(const TicketSpinLock &) = delete;

public:
    std::atomic<uint16_t> users;
    std::atomic<uint16_t> ticket;
};

class ScopedTicketSpinLock {
public:
    ScopedTicketSpinLock(TicketSpinLock &lock_) : lock(lock_) {
        auto me = lock.users++;
        while (unlikely(lock.ticket.load() != me))
#if __x86_64__
            asm volatile("rep;nop" : : : "memory");
#elif __aarch64__
#define __nops(n) ".rept " #n "\nnop\n.endr\n"
            asm volatile(__nops(1));
#else
#error arch unsupported!
#endif
    }
    ~ScopedTicketSpinLock() { ++lock.ticket; }

private:
    ScopedTicketSpinLock(const TicketSpinLock &) = delete;
    ScopedTicketSpinLock &operator=(const TicketSpinLock &) = delete;

private:
    TicketSpinLock &lock;
};

class AUTIL_LOCKABLE SpinLock {
public:
    void lock() AUTIL_EXCLUSIVE_LOCK_FUNCTION() {
        while (flag.test_and_set(std::memory_order_acquire))
            ;
    }
    void unlock() AUTIL_UNLOCK_FUNCTION() { flag.clear(std::memory_order_release); }

private:
    std::atomic_flag flag = ATOMIC_FLAG_INIT;
};

class AUTIL_SCOPED_LOCKABLE ScopedSpinLock {
public:
    ScopedSpinLock(SpinLock &lock) AUTIL_EXCLUSIVE_LOCK_FUNCTION(lock) : _lock(lock) { _lock.lock(); }
    ~ScopedSpinLock() AUTIL_UNLOCK_FUNCTION() { _lock.unlock(); }

private:
    ScopedSpinLock(const ScopedSpinLock &) = delete;
    ScopedSpinLock &operator=(const ScopedSpinLock &) = delete;

private:
    SpinLock &_lock;
};

namespace autil {

class ShortString {
public:
    typedef char *iterator;
    typedef const char *const_iterator;

public:
    ShortString() { init(); }
    ShortString(const char *s) { init(s, s + strlen(s)); }
    ShortString(const char *s, uint32_t len) { init(s, s + len); }
    ShortString(const std::string &s) { init(s.begin(), s.end()); }
    ShortString(const ShortString &s) { init(s.begin(), s.end()); }
    template <typename InputIterator>
    ShortString(InputIterator begin, InputIterator end) {
        init(begin, end);
    }
    ~ShortString() { deleteData(); }

public:
    ShortString &operator=(const char *s) { return assign(s); }
    ShortString &operator=(const std::string &s) { return assign(s); }
    ShortString &operator=(const ShortString &s) { return assign(s); }
    ShortString &operator+=(const ShortString &addStr);

public:
    ShortString &assign(const char *s) { return assign(s, s + strlen(s)); }
    ShortString &assign(const std::string &s) { return assign(s.begin(), s.end()); }
    ShortString &assign(const ShortString &s) {
        if (this == &s) {
            return *this;
        }
        return assign(s.begin(), s.end());
    }
    ShortString &assign(const char *s, uint32_t len) { return assign(s, s + len); }
    template <typename InputIterator>
    ShortString &assign(InputIterator begin, InputIterator end) {
        deleteData();
        init(begin, end);
        return *this;
    }

public:
    bool empty() const { return _size == 0; }
    size_t size() const { return _size; }
    size_t length() const { return size(); }
    iterator data() { return _data; }
    const_iterator data() const { return _data; }
    const char *c_str() const { return _data; }
    iterator begin() { return data(); }
    iterator end() { return data() + size(); }
    const_iterator begin() const { return data(); }
    const_iterator end() const { return data() + size(); }
    char &operator[](size_t pos) { return data()[pos]; }
    const char &operator[](size_t pos) const { return data()[pos]; }
    void clear() {
        deleteData();
        init();
    }

private:
    void init() {
        _size = 0;
        _data = _buf;
        _buf[0] = '\0';
    }

    template <typename InputIterator>
    void init(InputIterator begin, InputIterator end) {
        _size = std::distance(begin, end);
        initData();
        std::copy(begin, end, _data);
        _data[_size] = '\0';
    }

    void initData() {
        if (_size < BUF_SIZE) {
            _data = _buf;
        } else {
            _data = new char[_size + 1];
        }
    }

    void deleteData() {
        if (_data != _buf)
            delete[] _data;
    }

    void reserve(size_t size) {
        deleteData();
        _size = size;
        initData();
    }

public:
    // 99.99% token length < 43
    static const uint32_t BUF_SIZE = 48;

private:
    size_t _size;
    char *_data;
    char _buf[BUF_SIZE];

private:
    friend class ShortStringTest;
};

inline bool operator<(const ShortString &lhs, const ShortString &rhs) {
    return std::lexicographical_compare(lhs.begin(), lhs.end(), rhs.begin(), rhs.end());
}

inline bool operator<=(const ShortString &lhs, const ShortString &rhs) { return !(rhs < lhs); }

inline bool operator>(const ShortString &lhs, const ShortString &rhs) { return rhs < lhs; }

inline bool operator>=(const ShortString &lhs, const ShortString &rhs) { return !(lhs < rhs); }

inline bool operator==(const ShortString &lhs, const ShortString &rhs) {
    if (lhs.length() != rhs.length()) {
        return false;
    }
    return std::equal(lhs.begin(), lhs.end(), rhs.begin());
}

inline bool operator!=(const ShortString &lhs, const ShortString &rhs) { return !(lhs == rhs); }

inline std::istream &operator>>(std::istream &in, ShortString &s) {
    std::string tmp;
    in >> tmp;
    s = tmp;
    return in;
}

inline std::ostream &operator<<(std::ostream &out, const ShortString &s) {
    std::string tmp(s.begin(), s.end());
    out << tmp;
    return out;
}

