size_t len = (rem == 0) ? 0 : ((*FUZZ_PARAM(unsigned int)) % (rem + 1));
auto other = view->substr(pos, len);
bool ge = (*view >= other);
bool lt = (*view < other);
FUZZ_ASSERT(ge == !lt, "operator>= must be logical negation of operator<");
// Validation: Confirms relation between >= and <.

// Instantiate T=char for coverage; exercise both non-const and const overloads.
std::string s = FUZZ_PARAM_STR();
if (s.size() > 1024) { s.resize(1024); }
std::vector<char> v(s.begin(), s.end());
// Non-const overload -> autil::Span<char> (MutableStringView)
auto mspan = autil::SpanAdapter<std::vector<char>>::from(v);
FUZZ_ASSERT(mspan.size() == v.size(), "span size must equal vector size");
if (!v.empty()) {
    FUZZ_ASSERT(mspan.data() == v.data(), "span must reference vector storage");
}
// Const overload -> autil::ConstSpan<char> (StringView)
const std::vector<char> &cv = v;
auto cspan = autil::SpanAdapter<std::vector<char>>::from(cv);
FUZZ_ASSERT(cspan.size() == cv.size(), "const span size must equal vector size");
if (!cv.empty()) {
    FUZZ_ASSERT(cspan.data() == cv.data(), "const span must reference vector storage");
}
// No outputs returned because spans reference local vector memory.
// Validation: Verifies pointer/size aliasing for both overloads without leaking dangling views.

// Convert a span<char> back to std::vector<char> and validate copy semantics.
std::string s = FUZZ_PARAM_STR();
if (s.size() > 1024) { s.resize(1024); }
std::vector<char> v(s.begin(), s.end());
auto mspan = autil::SpanAdapter<std::vector<char>>::from(v);
std::vector<char> copy = autil::ExplicitSpanAdapter<std::vector<char>>::to(mspan);
FUZZ_ASSERT(copy.size() == v.size(), "ExplicitSpanAdapter<vector>::to must preserve size");
if (!v.empty()) {
    FUZZ_ASSERT(std::equal(copy.begin(), copy.end(), v.begin()), "vector copy must match original contents");
}
// Validation: Exercises allocation/copy path and checks content equality.

// Use T=char and a small N; exercise both const and non-const from().
constexpr size_t N = 16;
std::array<char, N> arr{};
// Fill with fuzz data up to N
std::string s = FUZZ_PARAM_STR();
for (size_t i = 0; i < N && i < s.size(); ++i) { arr[i] = s[i]; }
// Non-const
auto mspan = autil::SpanAdapter<std::array<char, N>>::from(arr);
FUZZ_ASSERT(mspan.size() == N, "span size must equal array size");
FUZZ_ASSERT(mspan.data() == arr.data(), "span must reference array storage");
// Const
const std::array<char, N> &carr = arr;
auto cspan = autil::SpanAdapter<std::array<char, N>>::from(carr);
FUZZ_ASSERT(cspan.size() == N, "const span size must equal array size");
FUZZ_ASSERT(cspan.data() == carr.data(), "const span must reference array storage");
// No outputs returned because spans reference stack memory.
// Validation: Confirms aliasing and sizing for array adapters.

// Create a StringView over std::string and validate aliasing.
std::string s = FUZZ_PARAM_STR();
if (s.size() > 1024) { s.resize(1024); }
auto sv = autil::SpanAdapter<std::string>::from(s); // autil::StringView
FUZZ_ASSERT(sv.size() == s.size(), "StringView size must equal string size");
if (!s.empty()) { FUZZ_ASSERT(sv.data() == s.data(), "StringView must alias string data"); }
// No outputs returned since StringView would alias local string memory.
// Validation: Ensures view-size equality and pointer aliasing.

// Copy from autil::StringView to std::string and validate contents.
std::string s2 = autil::ExplicitSpanAdapter<std::string>::to(*view);
FUZZ_ASSERT(s2.size() == view->size(), "to(StringView) must preserve size");
if (!view->empty()) {
    FUZZ_ASSERT(std::equal(s2.begin(), s2.end(), view->data()), "copied string must match view contents");
}
// Validation: Confirms allocation/copy correctness from view.

// Adapt from std::string_view to autil::StringView, validating aliasing.
std::string host = FUZZ_PARAM_STR();
if (host.size() > 1024) { host.resize(1024); }
std::string_view sv(host.data(), host.size());
auto av = autil::SpanAdapter<std::string_view>::from(sv);
FUZZ_ASSERT(av.size() == sv.size(), "StringView size must equal string_view size");
if (!sv.empty()) { FUZZ_ASSERT(av.data() == sv.data(), "StringView must alias string_view data"); }
// No outputs returned since view would alias local string memory.
// Validation: Ensures correct non-owning adaptation from std::string_view.

// Convert autil::StringView to std::string_view and validate non-owning aliasing.
std::string_view sv = autil::SpanAdapter<std::string_view>::to(*view);
FUZZ_ASSERT(sv.size() == view->size(), "conversion to std::string_view must preserve size");
if (!view->empty()) { FUZZ_ASSERT(sv.data() == view->data(), "std::string_view must alias view data"); }
// Validation: Confirms aliasing semantics and size preservation.

// Construct a SpinLock; it has implicit default state.
autil::SpinLock *sl = new autil::SpinLock();
// Track held state to prevent deadlock in single-threaded fuzzing.
FUZZ_SET_ATTR_INT(sl, "held", 0);
// Validation: Newly constructed SpinLock is unlocked; attribute mirrors state.

// Construct a ScopedSpinLock over the provided SpinLock input.
// Enforce precondition: do not acquire if already held to avoid deadlock in single-threaded fuzzing.
if (FUZZ_GET_ATTR_INT(sl, "held") != 0) { FUZZ_BAIL(); }
autil::ScopedSpinLock *ssl = new autil::ScopedSpinLock(*sl);
// Track association for safe teardown and state tracking.
FUZZ_SET_ATTR_PTR(ssl, "sl", sl);
FUZZ_SET_ATTR_INT(sl, "held", 1);
// Validation: RAII lock acquired; input lock returned to pool alongside the guard.

// Construct a MutableStringView (Span<char>) over a heap-backed buffer with fuzzer data.
// Keep buffer lifetime tied to this view via attributes to avoid dangling.
std::string seed = FUZZ_PARAM_STR();
if (seed.size() > 1024) seed.resize(1024);
size_t n = seed.size();
// Choose an effective view length within [0, n]
size_t eff = (n == 0) ? 0 : (size_t)(*FUZZ_PARAM(unsigned int) % (unsigned)(n + 1));
char *buf = nullptr;
if (eff > 0) {
    buf = new char[eff];
    memcpy(buf, seed.data(), eff);
}
// Prefer constructor taking (ptr, size) to avoid deprecated reset()
autil::MutableStringView *mview = new autil::MutableStringView(buf, eff);
// Validate invariants per span contract
if (eff == 0) {
    FUZZ_ASSERT(mview->size() == 0, "Empty MutableStringView must have size 0");
} else {
    FUZZ_ASSERT(mview->size() == eff, "MutableStringView size must equal requested length");
    FUZZ_ASSERT(mview->data() == buf, "MutableStringView must alias backing buffer");
}
// Track backing buffer for potential downstream use or cleanup stubs
FUZZ_SET_ATTR_PTR(mview, "backing", (void*)buf);
FUZZ_SET_ATTR_INT(mview, "size", (int)eff);
// Note: we intentionally leak small buffers (<1KB) per run if no destructor exists; acceptable under fuzz constraints.
// Validation: Constructs a valid span over owned heap memory; attributes record backing to avoid UAF.

// Construct a StringView (ConstSpan<char>) over a heap-backed buffer with fuzzer data.
// Buffer lifetime is tied to this view via attributes so it remains valid while pooled.
std::string seed = FUZZ_PARAM_STR();
if (seed.size() > 1024) seed.resize(1024);
size_t n = seed.size();
size_t eff = (n == 0) ? 0 : (size_t)(*FUZZ_PARAM(unsigned int) % (unsigned)(n + 1));
char *buf = nullptr;
if (eff > 0) {
    buf = new char[eff];
    memcpy(buf, seed.data(), eff);
}
// Prefer constructor (ptr, size) to avoid deprecated reset(); null with size 0 is permitted.
autil::StringView *view = new autil::StringView(buf, eff);
// Validate invariants
if (eff == 0) {
    FUZZ_ASSERT(view->size() == 0, "Empty StringView must report size 0");
} else {
    FUZZ_ASSERT(view->size() == eff, "StringView size must equal requested length");
    FUZZ_ASSERT(view->data() == (const char*)buf, "StringView must alias backing buffer");
}
// Record backing for downstream checks/cleanup stubs
FUZZ_SET_ATTR_PTR(view, "backing", (void*)buf);
FUZZ_SET_ATTR_INT(view, "size", (int)eff);
// Validation: Produces a non-owning view over owned heap memory, avoiding dangling pointers.

