import random
import struct
import string
from typing import List

# We generate valid, interesting arbitrary strings to exercise StringUtil and Span adapters.
# Strategy:
# - Mix cases: purely whitespace, alphanum with delimiters, hex strings (even/odd), numeric strings,
#   boolean literals, format strings, long repeated patterns, random bytes (including NUL), and
#   key=value pairs with various separators.
# - Ensure some inputs are paired-friendly (e.g., hex round-trip, serialize/deserialize friendliness),
#   while remaining within 4096 bytes.

MAX_SIZE = 4096

_WS = " \t\r\n\f\v"
_DELIMS = [",", "|", ":", ";", "::", "--", "..", " ", "\t"]
_SEPS = ["=", ":", "=>", "->", "::", "|", ",", "\t", " "]
_FMT_FRAGMENTS = [
    "%Y-%m-%d %H:%M:%S", "%s", "%f", "%g", "%e", "%08d", "[%d]", "{%s}",
    "%Y/%m/%d", "%H:%M:%S", "%z", "%j", "%m-%d-%Y", "%a %b %d %H:%M:%S %Y"
]
_BOOL_LITS = ["true", "false", "True", "False", "TRUE", "FALSE"]

def _rand_hex(r: random.Random, even: bool = True, length: int = None) -> bytes:
    if length is None:
        # choose small to medium length
        n = r.randint(0, 128)
    else:
        n = max(0, length)
    if even:
        n = n + (n & 1)  # make even
    # generate hex digits
    digs = '0123456789abcdefABCDEF'
    return ''.join(r.choice(digs) for _ in range(n)).encode('ascii')

def _rand_numeric(r: random.Random) -> bytes:
    kind = r.randint(0, 6)
    if kind == 0:
        return str(r.randint(-2**31, 2**31-1)).encode()
    if kind == 1:
        return str(r.randint(0, 2**32-1)).encode()
    if kind == 2:
        # float with format
        v = (r.randint(-10**6, 10**6)) / (10**r.randint(0,6) or 1)
        return ("%g" % v).encode()
    if kind == 3:
        # hex with 0x prefix
        return ("0x%X" % r.getrandbits(64)).encode()
    if kind == 4:
        # uint64 decimal
        return str(r.getrandbits(64)).encode()
    if kind == 5:
        # scientific
        v = (r.randint(-10**6, 10**6)) / (10**r.randint(0,6) or 1)
        return ("%e" % v).encode()
    else:
        # leading zeros
        return ("%010d" % r.randint(0, 999999)).encode()

def _rand_word(r: random.Random, min_len=1, max_len=16) -> str:
    alphabet = string.ascii_letters + string.digits
    n = r.randint(min_len, max_len)
    return ''.join(r.choice(alphabet) for _ in range(n))

def _rand_whitespace(r: random.Random, max_len=64) -> bytes:
    n = r.randint(0, max_len)
    return ''.join(r.choice(_WS) for _ in range(n)).encode()

def _rand_format_string(r: random.Random) -> bytes:
    # build a small printf-like or strftime-like format
    parts: List[str] = []
    count = r.randint(1, 6)
    for _ in range(count):
        if r.random() < 0.5:
            parts.append(r.choice(_FMT_FRAGMENTS))
        else:
            # raw text/literals including percent escaping
            lit = _rand_word(r, 0, 6)
            if r.random() < 0.3:
                lit = lit + "%%"  # percent sign
            parts.append(lit)
    s = r.choice([" ", "-", ":", "|", ","]).join(parts)
    # bound length
    return s[:128].encode('ascii', 'ignore')

def _rand_kv(r: random.Random) -> bytes:
    k = _rand_word(r, 0, 12)
    v = _rand_word(r, 0, 12)
    sep = r.choice(_SEPS)
    # optional spaces around
    pre = _rand_whitespace(r, 3).decode()
    post = _rand_whitespace(r, 3).decode()
    s = f"{pre}{k}{sep}{v}{post}"
    return s.encode('ascii', 'ignore')

def _rand_joined(r: random.Random) -> bytes:
    n = r.randint(1, 8)
    elems = [_rand_word(r, 0, 12) for _ in range(n)]
    sep = r.choice(_DELIMS)
    return sep.join(elems).encode('ascii', 'ignore')

def _rand_text(r: random.Random, max_len=256) -> bytes:
    # mixed ASCII including spaces and punctuation
    alphabet = string.ascii_letters + string.digits + string.punctuation + " "
    n = r.randint(0, max_len)
    return ''.join(r.choice(alphabet) for _ in range(n)).encode('utf-8', 'ignore')

def _rand_random_bytes(r: random.Random, max_len=256) -> bytes:
    n = r.randint(0, max_len)
    # include occasional NULs to test binary-safe paths
    return bytes(r.randrange(0, 256) for _ in range(n))

def _rand_boolean_literal(r: random.Random) -> bytes:
    return r.choice(_BOOL_LITS).encode()

def _hex_round_trip_seed(r: random.Random) -> bytes:
    # produce arbitrary bytes then hex-encode for guaranteed valid hex input
    raw = _rand_random_bytes(r, 64)
    hexstr = raw.hex()
    return hexstr.encode('ascii')

def _serialize_u32(r: random.Random) -> bytes:
    # simple portable little-endian 4-byte payload for deserializeUInt32 stubs
    # The actual impl is unknown, but fuzz stub uses library serializer before parser.
    # Here provide also plain decimal as a fallback interesting case.
    if r.random() < 0.5:
        v = r.getrandbits(32)
        return str(v).encode()
    else:
        v = r.getrandbits(32)
        return struct.pack('<I', v)

def _serialize_u64(r: random.Random) -> bytes:
    if r.random() < 0.5:
        v = r.getrandbits(64)
        return str(v).encode()
    else:
        v = r.getrandbits(64)
        return struct.pack('<Q', v)

def _pattern_repeat(r: random.Random) -> bytes:
    base = r.choice([b"abc", b"xyz", b"123", b"Aa", b"0x", b"--", b"::"]) \
           + (b"%d" if r.random() < 0.3 else b"")
    rep = r.randint(1, 128)
    data = base * rep
    return data[:512]

def _ensure_max(b: bytes) -> bytes:
    if len(b) > MAX_SIZE:
        return b[:MAX_SIZE]
    return b

GENERATORS = [
    lambda r: _rand_text(r, 512),
    lambda r: _rand_whitespace(r, 256),
    lambda r: _rand_joined(r),
    lambda r: _rand_kv(r),
    lambda r: _rand_numeric(r),
    lambda r: _rand_boolean_literal(r),
    lambda r: _rand_format_string(r),
    lambda r: _rand_hex(r, even=True),
    lambda r: _rand_hex(r, even=False),
    lambda r: _hex_round_trip_seed(r),
    lambda r: _serialize_u32(r),
    lambda r: _serialize_u64(r),
    lambda r: _rand_random_bytes(r, 512),
    lambda r: _pattern_repeat(r),
]

def generate(seed: int) -> bytes:
    r = random.Random(seed)
    # Choose 1-4 segments and join with random separators to produce diverse strings
    segments: List[bytes] = []
    count = r.randint(1, 4)
    for _ in range(count):
        gen = r.choice(GENERATORS)
        seg = gen(r)
        segments.append(seg)
        # occasionally insert delimiters between segments to help split/replace
        if r.random() < 0.7:
            delim = r.choice([b",", b"|", b":", b";", b" ", b"\t", b"--", b"::"]) \
                    * r.randint(1, 3)
            segments.append(delim)
    data = b"".join(segments)
    # Occasionally wrap with leading/trailing whitespace to exercise trim
    if r.random() < 0.6:
        data = _rand_whitespace(r, 16) + data + _rand_whitespace(r, 16)
    # Keep within size constraints
    data = _ensure_max(data)
    return data

import random
import string
from typing import List

# This generator produces valid numeric strings suitable for autil::StringUtil strTo* parsers.
# It aims to cover:
# - signed/unsigned ranges for 8/16/32/64-bit
# - optional leading/trailing whitespace (spaces, tabs, newlines)
# - explicit plus/minus signs where applicable
# - boundary values (min/max) and values around them
# - zero in various forms
# - large 64-bit values
# The output is a bytes object (ASCII) with no embedded NULs; C++ side uses c_str().

WS = ["", " ", "\t", "\n", "  ", "\t\t", " \t", "\n \t "]

INT_LIMITS = {
    8:  (-(1 << 7), (1 << 7) - 1),
    16: (-(1 << 15), (1 << 15) - 1),
    32: (-(1 << 31), (1 << 31) - 1),
    64: (-(1 << 63), (1 << 63) - 1),
}
UINT_LIMITS = {
    8:  (0, (1 << 8) - 1),
    16: (0, (1 << 16) - 1),
    32: (0, (1 << 32) - 1),
    64: (0, (1 << 64) - 1),
}


def pick_ws(rng: random.Random) -> str:
    return rng.choice(WS)


def surround_ws(rng: random.Random, core: str) -> str:
    return f"{pick_ws(rng)}{core}{pick_ws(rng)}"


def with_sign(rng: random.Random, val: int, allow_plus: bool = True) -> str:
    if val < 0:
        return str(val)
    # zero or positive
    mode = rng.randint(0, 2 if allow_plus else 1)
    if mode == 0:
        return str(val)
    elif mode == 1 and allow_plus:
        return "+" + str(val)
    else:
        return str(val)


def neighbors(val: int, lo: int, hi: int) -> List[int]:
    cands = [val]
    for d in (-1, 1, -2, 2, -10, 10):
        vv = val + d
        if lo <= vv <= hi:
            cands.append(vv)
    return list(dict.fromkeys(cands))


def boundary_values_signed(bits: int) -> List[int]:
    lo, hi = INT_LIMITS[bits]
    vals = [lo, hi, 0, -1, 1]
    vals += neighbors(lo, lo, hi)
    vals += neighbors(hi, lo, hi)
    return list(dict.fromkeys([v for v in vals if lo <= v <= hi]))


def boundary_values_unsigned(bits: int) -> List[int]:
    lo, hi = UINT_LIMITS[bits]
    vals = [lo, hi, 0, 1]
    vals += neighbors(lo, lo, hi)
    vals += neighbors(hi, lo, hi)
    return list(dict.fromkeys([v for v in vals if lo <= v <= hi]))


def random_in_range(rng: random.Random, lo: int, hi: int) -> int:
    if hi - lo < (1 << 31):
        return rng.randint(lo, hi)
    # For 64-bit full range, compose to avoid biases
    span = hi - lo
    # generate 64-bit uniform
    v = (rng.getrandbits(64) & ((1 << 63) - 1))  # non-negative 63-bit
    # scale to span+1 using modulo (accept small bias; fine for fuzz seeding)
    return lo + (v % (span + 1))


def gen_signed_numeric_string(rng: random.Random, bits: int) -> str:
    lo, hi = INT_LIMITS[bits]
    choice = rng.random()
    if choice < 0.45:
        v = rng.choice(boundary_values_signed(bits))
    elif choice < 0.9:
        v = random_in_range(rng, lo, hi)
    else:
        # values near zero
        v = rng.choice([-2, -1, 0, 1, 2])
        v = max(lo, min(hi, v))
    s = with_sign(rng, v, allow_plus=True)
    return surround_ws(rng, s)


def gen_unsigned_numeric_string(rng: random.Random, bits: int) -> str:
    lo, hi = UINT_LIMITS[bits]
    choice = rng.random()
    if choice < 0.45:
        v = rng.choice(boundary_values_unsigned(bits))
    elif choice < 0.9:
        v = random_in_range(rng, lo, hi)
    else:
        v = rng.choice([0, 1, 2, 10])
    s = with_sign(rng, v, allow_plus=True)
    return surround_ws(rng, s)


def interesting_set(rng: random.Random) -> List[str]:
    out: List[str] = []
    # Signed 8/16/32/64
    for b in (8, 16, 32, 64):
        for _ in range(rng.randint(2, 4)):
            out.append(gen_signed_numeric_string(rng, b))
    # Unsigned 8/16/32/64
    for b in (8, 16, 32, 64):
        for _ in range(rng.randint(2, 4)):
            out.append(gen_unsigned_numeric_string(rng, b))
    # Special canonical forms
    specials = [
        surround_ws(rng, "+0"),
        surround_ws(rng, "-0"),
        surround_ws(rng, "0"),
        surround_ws(rng, "+123"),
        surround_ws(rng, "-123"),
        surround_ws(rng, str(UINT_LIMITS[64][1])),
        surround_ws(rng, str(INT_LIMITS[64][0])),
        surround_ws(rng, str(INT_LIMITS[64][1])),
    ]
    out.extend(specials)
    # Deduplicate while preserving order
    seen = set()
    uniq: List[str] = []
    for s in out:
        if s not in seen:
            seen.add(s)
            uniq.append(s)
    return uniq


def pack_lines(lines: List[str]) -> bytes:
    # Join with newlines to let FUZZ_PARAM_STR() receive a reasonable slice; also
    # FUZZ_PARAM_FILENAME data readers can consume line-wise.
    blob = "\n".join(lines)
    # Ensure size limit
    data = blob.encode("ascii", errors="strict")
    if len(data) > 4096:
        data = data[:4096]
    return data


def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    lines = interesting_set(rng)
    # Shuffle to vary ordering per seed
    rng.shuffle(lines)
    # Ensure at least one tiny and one long-ish decimal within limits
    lines.insert(0, surround_ws(rng, str(rng.randint(-9999, 9999))))
    # Add a long 64-bit edge-neighbor
    lo64, hi64 = INT_LIMITS[64]
    near_edges = [hi64 - rng.randint(0, 20), lo64 + rng.randint(0, 20)]
    lines.extend(surround_ws(rng, str(v)) for v in near_edges)
    return pack_lines(lines)

import random
import struct
import math
from typing import List

# Generate interesting, valid floating-point strings covering many formats that
# autil::StringUtil::strToFloat/Double likely accept. We keep output <= 4096 bytes.

_WS = ["", " ", "\t", "\n", "\r", "\f", "\v", "  \t\n  "]
_SIGNS = ["", "+", "-"]
_EXP_SEPS = ["e", "E"]
_INF_TOKENS = ["inf", "+inf", "-inf", "infinity", "+infinity", "-infinity"]
_NAN_TOKENS = ["nan", "+nan", "-nan", "nan(payload)", "-nan(payload)"]

# Utilities to build numeric strings in various formats

def _rnd_float(rng: random.Random) -> float:
    # Bias to interesting magnitudes
    choices = [
        0.0, -0.0, 1.0, -1.0, 10.0, -10.0, 1e-6, -1e-6, 1e6, -1e6,
        math.pi, -math.pi, math.e, -math.e,
        3.4028235e38, 1.17549435e-38,  # float max/min normal
    ]
    if rng.random() < 0.6:
        # Random mantissa and exponent
        mant = rng.uniform(-1.0, 1.0)
        exp = rng.randint(-38, 38)
        val = mant * (10.0 ** exp)
    else:
        val = rng.choice(choices)
    # Occasionally make subnormal-ish small values
    if rng.random() < 0.1:
        val *= 1e-45
    return float(val)


def _fmt_fixed(val: float, rng: random.Random) -> str:
    # Choose precision sensibly
    prec = rng.randint(0, 10)
    return f"{val:.{prec}f}"


def _fmt_general(val: float, rng: random.Random) -> str:
    prec = rng.randint(1, 12)
    return f"{val:.{prec}g}"


def _fmt_scientific(val: float, rng: random.Random) -> str:
    prec = rng.randint(0, 10)
    s = f"{val:.{prec}e}"
    # Randomize exponent letter case and zero padding
    if rng.random() < 0.5:
        s = s.replace("e", "E")
    # Optionally zero-pad exponent to at least 2 digits
    if rng.random() < 0.5:
        # find E or e and pad exponent
        for ch in ("E", "e"):
            if ch in s:
                base, exp = s.split(ch, 1)
                sign = "+" if exp.startswith("+") else ("-" if exp.startswith("-") else "")
                rest = exp[len(sign):]
                rest = rest.zfill(rng.choice([2, 3]))
                s = base + ch + sign + rest
                break
    return s


def _fmt_integer_like(val: float, rng: random.Random) -> str:
    # Format as integer string (no decimal point), maybe with sign
    ival = int(val)
    s = str(abs(ival))
    if rng.random() < 0.5 and len(s) > 3:
        # add underscores or not? Many parsers reject underscores; keep numeric only
        pass
    sign = rng.choice(["", "+", "-"])
    if ival == 0 and sign == "-":
        sign = rng.choice(["", "+"])  # avoid "-0" sometimes; but allow occasionally
        if rng.random() < 0.3:
            sign = "-"
    return sign + s


def _maybe_trailing_dot(s: str, rng: random.Random) -> str:
    # Some parsers accept trailing dot (e.g., "1.")
    if rng.random() < 0.3 and s and s[-1].isdigit():
        return s + "."
    return s


def _maybe_leading_dot(s: str, rng: random.Random) -> str:
    # Some parsers accept leading dot (e.g., ".5")
    if rng.random() < 0.3:
        # extract sign
        sign = ""
        body = s
        if body and body[0] in "+-":
            sign = body[0]
            body = body[1:]
        # if body looks like digits only, make it ".digits"
        if body.isdigit():
            return sign + "." + body
    return s


def _add_exponent(s: str, rng: random.Random) -> str:
    if rng.random() < 0.6:
        e = rng.choice(_EXP_SEPS)
        esign = rng.choice(_SIGNS)
        expv = rng.randint(0, 308)
        # Occasionally pad with zeros
        if rng.random() < 0.4:
            exp = f"{esign}{str(expv).zfill(rng.choice([2,3]))}"
        else:
            exp = f"{esign}{expv}"
        s = s + e + exp
    return s


def _surround_ws(s: str, rng: random.Random) -> str:
    return rng.choice(_WS) + s + rng.choice(_WS)


def _maybe_sign(s: str, rng: random.Random) -> str:
    if rng.random() < 0.5 and (not s or s[0] not in "+-"):
        return rng.choice(["+", "-"]) + s
    return s


def _decimal_body(rng: random.Random) -> str:
    # Build decimal with optional integer and fractional parts
    int_part_len = rng.randint(0, 8)
    frac_part_len = rng.randint(0, 10)
    int_part = ''.join(rng.choice('0123456789') for _ in range(int_part_len))
    frac_part = ''.join(rng.choice('0123456789') for _ in range(frac_part_len))
    if int_part == "":
        if frac_part == "":
            int_part = str(rng.randint(0, 9))
            frac_part = ''
            dot = ''
        else:
            dot = "."
    else:
        dot = "." if rng.random() < 0.8 else ""
    return int_part + dot + frac_part


def _make_numeric_string(rng: random.Random) -> str:
    choice = rng.random()
    if choice < 0.25:
        v = _rnd_float(rng)
        s = _fmt_general(v, rng)
    elif choice < 0.5:
        v = _rnd_float(rng)
        s = _fmt_fixed(v, rng)
        s = _maybe_trailing_dot(s, rng)
    elif choice < 0.75:
        v = _rnd_float(rng)
        s = _fmt_scientific(v, rng)
    else:
        s = _decimal_body(rng)
        s = _maybe_leading_dot(s, rng)
        s = _add_exponent(s, rng)
        s = _maybe_sign(s, rng)
    # Occasionally force integer-like without decimal but with exponent
    if rng.random() < 0.2:
        v = _rnd_float(rng)
        s = _fmt_integer_like(v, rng)
        s = _add_exponent(s, rng)
    # Surround with whitespace sometimes
    s = _surround_ws(s, rng)
    return s


def _make_special_token(rng: random.Random) -> str:
    tok = rng.choice(_INF_TOKENS + _NAN_TOKENS)
    # Random casing variations
    def rc(x: str) -> str:
        out = []
        for ch in x:
            if ch.isalpha() and rng.random() < 0.5:
                out.append(ch.upper())
            else:
                out.append(ch.lower())
        return ''.join(out)
    tok = rc(tok)
    return _surround_ws(tok, rng)


def _maybe_junk_suffix_prefix(s: str, rng: random.Random) -> str:
    # Some parsers accept leading/trailing plus/minus or parentheses around NaN payloads already covered.
    # Keep it valid: only add surrounding parentheses for numbers rarely.
    if rng.random() < 0.05:
        s = "(" + s + ")"
    return s


def _blend_cases(seed: int, rng: random.Random) -> List[str]:
    cases: List[str] = []
    # A mix of numbers and specials likely to drive both success and default paths in stubs
    for _ in range(rng.randint(5, 20)):
        if rng.random() < 0.2:
            s = _make_special_token(rng)
        else:
            s = _make_numeric_string(rng)
        s = _maybe_junk_suffix_prefix(s, rng)
        cases.append(s)
    # Ensure guaranteed-valid representatives
    cases += [
        "0", "-0", " +0.0 ", "1.", ".5", "-3.1415926", "6.02e23", "-1e-9",
        " nan ", " -inf ", " +INF ", " NaN ",
    ]
    # Deduplicate while preserving order
    seen = set()
    uniq = []
    for c in cases:
        if c not in seen:
            seen.add(c)
            uniq.append(c)
    return uniq


def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    # Build a newline-separated corpus of float strings; FUZZ_PARAM_STR() often consumes
    # a single blob or pieces. Providing multiple lines increases coverage while staying valid.
    lines = _blend_cases(seed, rng)
    blob = "\n".join(lines)
    data = blob.encode("utf-8", errors="strict")
    # Ensure not exceeding 4096 bytes; if too large, truncate at line boundary
    if len(data) > 4096:
        # Keep as many full lines as fit
        out = bytearray()
        for line in lines:
            b = (line + "\n").encode("utf-8")
            if len(out) + len(b) > 4096:
                break
            out += b
        data = bytes(out)
        if not data:
            data = b"0\n"
    return data
